tool.command:
        mkdir -p cminet_inputs cminet_outputs ;
        export CMINET_OUTPUT_DIR=\$PWD/cminet_outputs ;
#if $abundance_table
        cp -f '$abundance_table' cminet_inputs/abundance ;
#end if
#if $weighted_network
        cp -f '$weighted_network' cminet_inputs/weighted_network ;
#end if
        exec /usr/local/bin/cminet-entrypoint
